# PreToolUse guard: reject direct edits to generated files.
# Reads the Claude Code hook payload from stdin and exits 2 to deny.

$ErrorActionPreference = 'Stop'

$raw = [Console]::In.ReadToEnd()
if ([string]::IsNullOrWhiteSpace($raw)) { exit 0 }

try { $payload = $raw | ConvertFrom-Json } catch { exit 0 }

$toolInput = $payload.tool_input
if ($null -eq $toolInput) { exit 0 }

$path = $toolInput.file_path
if ([string]::IsNullOrWhiteSpace($path)) { exit 0 }

$cwd = $payload.cwd
if ([string]::IsNullOrWhiteSpace($cwd)) { $cwd = (Get-Location).Path }

try {
    if ([System.IO.Path]::IsPathRooted($path)) {
        $full = [System.IO.Path]::GetFullPath($path)
    } else {
        $full = [System.IO.Path]::GetFullPath((Join-Path $cwd $path))
    }
    $root = [System.IO.Path]::GetFullPath($cwd)
} catch {
    exit 0
}

$rel = $full
if ($full.StartsWith($root, [System.StringComparison]::OrdinalIgnoreCase)) {
    $rel = $full.Substring($root.Length)
}
$rel = $rel.TrimStart('\', '/') -replace '\\', '/'

$reason = $null
switch -Regex ($rel) {
    '^internal/db/[^/]+\.sql\.go$' {
        $reason = 'internal/db/*.sql.go is generated by sqlc. Edit internal/db/sql/*.sql or internal/db/migrations/*.sql, then run `sqlc generate`.'
        break
    }
    '^internal/db/(db|models|querier)\.go$' {
        $reason = 'This file is generated by sqlc. Edit the SQL sources, then run `sqlc generate`.'
        break
    }
    '^schema\.json$' {
        $reason = 'schema.json is generated. Edit internal/config/config.go or internal/shellconfig/options.go, then run `go run main.go schema > schema.json`.'
        break
    }
    '^internal/agent/hyper/provider\.json$' {
        $reason = 'provider.json is generated. Run `go generate ./internal/agent/hyper/...`.'
        break
    }
}

if ($reason) {
    [Console]::Error.WriteLine($reason)
    exit 2
}

exit 0
